-- Read-only catalog and approved synthetic identity counts; no financial row contents.

SELECT n.nspname AS schema, count(*) AS tables, count(*) FILTER(WHERE c.relrowsecurity) AS rls, count(*) FILTER(WHERE c.relforcerowsecurity) AS forced FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','fingence_reconciliation','fingence_db04_group_synthetic') AND c.relkind='r' GROUP BY n.nspname ORDER BY n.nspname;

SELECT 'unvalidated_constraints' AS check, count(*)::text AS observed FROM pg_constraint x JOIN pg_namespace n ON n.oid=x.connamespace WHERE n.nspname IN ('public','fingence_reconciliation','fingence_db04_group_synthetic') AND NOT x.convalidated UNION ALL SELECT 'reconciliation_foreign_keys',count(*)::text FROM pg_constraint x JOIN pg_namespace n ON n.oid=x.connamespace WHERE n.nspname='fingence_reconciliation' AND x.contype='f' UNION ALL SELECT 'reconciliation_indexes',count(*)::text FROM pg_indexes WHERE schemaname='fingence_reconciliation' UNION ALL SELECT 'immutable_triggers',count(*)::text FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='fingence_reconciliation' AND t.tgname='immutable' UNION ALL SELECT 'public_financial_grants',count(*)::text FROM pg_roles r CROSS JOIN pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE r.rolname IN ('anon','authenticated','service_role') AND n.nspname IN ('public','fingence_reconciliation','fingence_db04_group_synthetic') AND c.relkind='r' AND (has_table_privilege(r.oid,c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,TRIGGER') OR has_any_column_privilege(r.oid,c.oid,'SELECT,INSERT,UPDATE')) UNION ALL SELECT 'unsafe_security_definers',count(*)::text FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('fingence_reconciliation','fingence_db04_group_synthetic') AND p.prosecdef AND NOT COALESCE('search_path=pg_catalog'=ANY(p.proconfig),false) UNION ALL SELECT 'wrong_numeric_types',count(*)::text FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE ((n.nspname='public' AND c.relname='financial_records' AND a.attname IN ('debit','credit','source_amount','derived_ledger_net','balance')) OR (n.nspname='fingence_reconciliation' AND c.relname='transactions' AND a.attname='signed_amount')) AND a.atttypid<>'numeric'::regtype;

SELECT 'synthetic_organizations' AS check,count(*)::text AS observed FROM fingence_db04_group_synthetic.organizations UNION ALL SELECT 'synthetic_users',count(*)::text FROM fingence_db04_group_synthetic.users UNION ALL SELECT 'synthetic_memberships',count(*)::text FROM fingence_db04_group_synthetic.memberships UNION ALL SELECT 'organization_states',count(*)::text FROM fingence_db04_group_synthetic.organization_states UNION ALL SELECT 'disabled_restricted_logins',count(*)::text FROM pg_roles WHERE rolname IN ('db04_group_test_runtime','db04_group_test_broker') AND NOT rolcanlogin AND NOT rolsuper AND NOT rolbypassrls AND NOT rolcreatedb AND NOT rolcreaterole AND NOT rolreplication UNION ALL SELECT 'broker_financial_grants',count(*)::text FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='fingence_reconciliation' AND c.relkind='r' AND has_table_privilege('db04_group_test_broker',c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,TRIGGER') UNION ALL SELECT 'runtime_foundation_grants',count(*)::text FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind='r' AND has_table_privilege('db04_group_test_runtime',c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,TRIGGER');
